-- rebuild-carnet 069 + 070 + 071 + 072 + 073 + 074 (2026-09-28): remap reader reports to the new paragraph IDs.
-- paragraph_reports is the only table keyed by paragraph ID (src/auth/init.sql).
-- Reading history / bookmarks live in each reader's localStorage and cannot be remapped here.
-- One UPDATE through a mapping table, so a chain like 0005→0006→0007 cannot double-apply.
BEGIN;
CREATE TEMP TABLE renumber_069_070_071_072_073_074 (old_id TEXT PRIMARY KEY, new_id TEXT NOT NULL) ON COMMIT DROP;
UPDATE paragraph_reports r SET paragraph_id = m.new_id FROM renumber_069_070_071_072_073_074 m WHERE r.paragraph_id = m.old_id;
COMMIT;
